	public static int getBaseAnimationId(int id) {
		for (int[] ints : ids) {
			for (int anInt : ints) {
				if (anInt == id) {
					for (int i : ints) {
						if (i != -1) return i;
					}
					return ints[0];
				}
			}
		}
		return id;
	}
