	@Override
	public void keyPressed(KeyEvent ev)
	{
		if (!chatboxPanelManager.shouldTakeInput())
		{
			return;
		}

		switch (ev.getKeyCode())
		{
			case KeyEvent.VK_ENTER:
				ev.consume();
				if (index > -1)
				{
					itemSelected(results.get(index));
                }
                break;
            case KeyEvent.VK_TAB:
            case KeyEvent.VK_RIGHT:
                ev.consume();
                if (!results.isEmpty())
                {
                    index++;
                    if (index >= results.size())
                    {
                        index = 0;
                    }
                    clientThread.invokeLater(this::update);
                }
                break;
            case KeyEvent.VK_LEFT:
                ev.consume();
                if (!results.isEmpty())
                {
                    index--;
                    if (index < 0)
                    {
                        index = results.size() - 1;
                    }
                    clientThread.invokeLater(this::update);
                }
                break;
            case KeyEvent.VK_UP:
                ev.consume();
                if (results.size() >= (RESULTS_PER_PAGE / 2))
                {
                    index -= RESULTS_PER_PAGE / 2;
                    if (index < 0)
                    {
                        if (results.size() == RESULTS_PER_PAGE)
                        {
                            index += results.size();
                        }
                        else
                        {
                            index += RESULTS_PER_PAGE;
                        }
                        index = Ints.constrainToRange(index, 0, results.size() - 1);
                    }

                    clientThread.invokeLater(this::update);
                }
                break;
            case KeyEvent.VK_DOWN:
                ev.consume();
                if (results.size() >= (RESULTS_PER_PAGE / 2))
                {
                    index += RESULTS_PER_PAGE / 2;
                    if (index >= RESULTS_PER_PAGE)
                    {
                        if (results.size() == RESULTS_PER_PAGE)
                        {
                            index -= results.size();
                        }
                        else
                        {
                            index -= RESULTS_PER_PAGE;
                        }
                        index = Ints.constrainToRange(index, 0, results.size() - 1);
                    }

                    clientThread.invokeLater(this::update);
                }
                break;
            default:
                super.keyPressed(ev);
        }
    }

    @Override
    protected void close()
    {
    	if (onItemMouseOvered != null) onItemMouseOvered.accept(-1);

        // Clear search string when closed
        value("");
        results.clear();
        spells.clear();
        index = -1;
        mode = 0;
        searchType = null;
        super.close();
    }

