			{
				if (!nameInput.getTextField().isEditable()) {
					plugin.clientThread.invokeLater(() -> {
						transmogSet.setMinimized(!transmogSet.isMinimized());
						SwingUtilities.invokeLater(TransmogSetPanel.this::rebuild);
					});
